CID = 'comprehensions'
LOOP1, WHERE, NEST, SDG, CHOOSE, MUT = "A loop in one line", "Where does if go? Filter vs transform", "Nested comprehensions", "Set and dict comprehensions, and generator expressions", "Choosing the right collection", "Mutable, immutable and hashable"
def W(lv, sec, q, starter, sol, e): return dict(lv=lv, ty='code', sec=sec, q=q, starter=starter, sol=sol, e=e)
def F(lv, sec, q, c, fixed, e): return dict(lv=lv, ty='fix', sec=sec, q=q, c=c, fixed=fixed, e=e)
def T(lv, sec, c, e): return dict(lv=lv, ty='type', sec=sec, q="Type exactly what this code prints.", c=c, e=e)
Q = [
 # ---------- Basic ----------
 T(1, LOOP1, 'print([n * 3 for n in range(1, 5)])', "The comprehension runs `n * 3` for n = 1, 2, 3 and 4, and collects the answers in a list."),
 W(1, LOOP1, '`prices = [100, 250, 80]`. Use a list comprehension to make a new list with each price doubled, and print it.', 'prices = [100, 250, 80]\n', 'prices = [100, 250, 80]\nprint([p * 2 for p in prices])', "`[expression for item in list]`: the expression is worked out once for every item."),
 W(1, WHERE, '`ages = [12, 25, 17, 40, 15]`. Use a list comprehension to keep only the adults (18 or more), and print the list.', 'ages = [12, 25, 17, 40, 15]\n', 'ages = [12, 25, 17, 40, 15]\nprint([a for a in ages if a >= 18])', "An `if` at the end is a filter: it decides which items get in."),
 W(1, LOOP1, '`cities = [" delhi", "PUNE ", "goa"]`. Clean them with `strip()` and `title()` in a list comprehension, and print the list.', 'cities = [" delhi", "PUNE ", "goa"]\n', 'cities = [" delhi", "PUNE ", "goa"]\nprint([c.strip().title() for c in cities])', "Any expression works in a comprehension, including chained string methods."),
 W(1, SDG, 'Print the sum of the squares of 1 to 10, using a generator expression inside `sum()`.', '# sum(... for n in range(1, 11))\n', 'print(sum(n * n for n in range(1, 11)))', "A generator expression has no square brackets. `sum()` takes its values one at a time without building a list."),
 F(1, WHERE, "This code should replace negative numbers with 0 and print `[0, 7, 0]`, but it crashes. Fix it.", 'nums = [-3, 7, -1]\nprint([x for x in nums if x > 0 else 0])', 'nums = [-3, 7, -1]\nprint([x if x > 0 else 0 for x in nums])', "A filter `if` (at the end) cannot have an `else`. To change values, put `x if ... else ...` at the front, before `for`."),
 T(1, WHERE, 'print(["high" if n > 50 else "low" for n in [20, 80, 55]])', "The ternary at the front picks a value for every item, so the list always has 3 items."),
 F(1, LOOP1, "This code should print `[1, 4, 9]`, but it crashes. Fix it.", 'squares = [x ** 2 for x in range(1, 4)\nprint(squares)', 'squares = [x ** 2 for x in range(1, 4)]\nprint(squares)', "The comprehension opens with `[`, so it must close with `]`."),
 # ---------- Medium ----------
 W(2, SDG, '`emails = ["A@x.in", "a@x.in", "b@x.in"]`. Use a set comprehension with `lower()` to get the different emails, and print them sorted.', 'emails = ["A@x.in", "a@x.in", "b@x.in"]\n', 'emails = ["A@x.in", "a@x.in", "b@x.in"]\nprint(sorted({e.lower() for e in emails}))', "Curly brackets make a set comprehension: values that become equal after `lower()` are kept once."),
 W(2, SDG, '`words = ["tea", "coffee", "juice"]`. Make a dictionary of each word and its length with a dictionary comprehension, and print it.', 'words = ["tea", "coffee", "juice"]\n', 'words = ["tea", "coffee", "juice"]\nprint({w: len(w) for w in words})', "A dictionary comprehension has `key: value` before the `for`."),
 T(2, NEST, 'print([(i, j) for i in range(2) for j in "xy"])', "With two `for`s, the first one is the outer loop: for each `i`, the inner loop runs through `x` and `y`."),
 W(2, NEST, '`weeks = [[3, 5], [2], [4, 1, 6]]`. Flatten it into one list with a nested comprehension, and print it.', 'weeks = [[3, 5], [2], [4, 1, 6]]\n', 'weeks = [[3, 5], [2], [4, 1, 6]]\nprint([n for week in weeks for n in week])', "Read it like two nested loops: for each week, for each number in that week."),
 F(2, NEST, "This code should change only the first row and print `[[9, 0, 0], [0, 0, 0]]`. Fix it.", 'grid = [[0] * 3] * 2\ngrid[0][0] = 9\nprint(grid)', 'grid = [[0] * 3 for _ in range(2)]\ngrid[0][0] = 9\nprint(grid)', "`[row] * 2` repeats the same inner list twice, so both rows change together. A comprehension makes a new row each time."),
 W(2, WHERE, '`marks = [45, 82, 30, 67]`. Print a list with `"P"` or `"F"` for each mark (35 or more passes). Then print a second list with only the passing marks.', 'marks = [45, 82, 30, 67]\n', 'marks = [45, 82, 30, 67]\nprint(["P" if m >= 35 else "F" for m in marks])\nprint([m for m in marks if m >= 35])', "Transform: the ternary goes at the front and every item gets a value. Filter: the `if` goes at the end and some items are dropped."),
 T(2, SDG, 'print(sorted({len(w) for w in ["hi", "yes", "no", "ok"]}), sum(1 for w in ["a", "bb", "a"] if w == "a"))', "The set keeps the different lengths (2 and 3). `sum(1 for ... if ...)` counts the matching items."),
 W(2, CHOOSE, '`visits = [101, 102, 101, 103]`. Store the unique visitor IDs in the right collection, and the fixed location `17.38, 78.48` in the right collection. Print the number of unique IDs and the two types, with one `print()`.', 'visits = [101, 102, 101, 103]\n', 'visits = [101, 102, 101, 103]\nunique_ids = set(visits)\nlocation = (17.38, 78.48)\nprint(len(unique_ids), type(unique_ids), type(location))', "Unique values belong in a set. A fixed pair that never changes belongs in a tuple."),
 W(2, SDG, '`stock = {"pen": 0, "ink": 4, "pad": 0, "gel": 9}`. Use a dictionary comprehension to keep only the items that are in stock (more than 0), and print it.', 'stock = {"pen": 0, "ink": 4, "pad": 0, "gel": 9}\n', 'stock = {"pen": 0, "ink": 4, "pad": 0, "gel": 9}\nprint({item: n for item, n in stock.items() if n > 0})', "Loop over `items()` to get both key and value, and filter with `if` at the end."),
 F(2, MUT, "This code should print `Hyderabad`, but it crashes. Fix it.", 'locations = {[17.38, 78.48]: "Hyderabad"}\nprint(locations[[17.38, 78.48]])', 'locations = {(17.38, 78.48): "Hyderabad"}\nprint(locations[(17.38, 78.48)])', "A list can change, so it is not hashable and cannot be a key. A tuple is immutable and works as a key."),
 # ---------- Challenge (same chapter, combined) ----------
 W(3, NEST, '`matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]`. Make a list of the even numbers in the matrix with one nested comprehension, and print it.', 'matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]\n', 'matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]\nprint([n for row in matrix for n in row if n % 2 == 0])', "Both `for`s come first (outer, then inner), and the filter goes at the very end."),
 W(3, SDG, '`sales = {"Mon": 1200, "Tue": 800, "Wed": 1500}`. With one `print()`, show the total (a generator expression over `values()`) and a dictionary of the days above 1000 (a dictionary comprehension).', 'sales = {"Mon": 1200, "Tue": 800, "Wed": 1500}\n', 'sales = {"Mon": 1200, "Tue": 800, "Wed": 1500}\nprint(sum(v for v in sales.values()), {d: v for d, v in sales.items() if v > 1000})', "A generator expression feeds `sum()` directly, and the dictionary comprehension filters the days in one line."),
 W(3, WHERE, '`raw = ["12", "NA", "7", "", "30"]`. Use one list comprehension to keep only the entries that are made of digits (`isdigit()`) and turn them into ints. Print the list and its sum.', 'raw = ["12", "NA", "7", "", "30"]\n', 'raw = ["12", "NA", "7", "", "30"]\nclean = [int(x) for x in raw if x.isdigit()]\nprint(clean, sum(clean))', "The filter runs first, so `int()` only sees text that really is a number. An empty string is not `isdigit()`."),
 T(3, MUT, 'a = [1, 2]\nb = a\nb += [3]\nt = (1, 2)\nu = t\nu += (3,)\nprint(a, t)', "`+=` changes a list in place, so `a` sees it too. A tuple cannot change, so `u += (3,)` makes a new tuple and `t` stays the same."),
 W(3, NEST, '`m = [[1, 2, 3], [4, 5, 6]]`. Transpose it (rows become columns) with a nested comprehension, and print the result.', 'm = [[1, 2, 3], [4, 5, 6]]\n', 'm = [[1, 2, 3], [4, 5, 6]]\nprint([[row[i] for row in m] for i in range(3)])', "The outer comprehension builds one new row per column index `i`; the inner one takes item `i` from every old row."),
 F(3, SDG, "This code should print the different words, sorted: `['data', 'python']`. Fix it.", 'words = ["data", "Data", "python"]\nunique = {w.lower() for w in words}\nprint(unique[0])', 'words = ["data", "Data", "python"]\nunique = {w.lower() for w in words}\nprint(sorted(unique))', "A set has no index. `sorted()` turns it into a sorted list that you can print or index."),
 W(3, WHERE, '`names = ["Asha", "ravi", "Anil", "neha"]`. Make a dictionary of each name in title case and its length, only for names that start with "a" in any case. Print it.', 'names = ["Asha", "ravi", "Anil", "neha"]\n', 'names = ["Asha", "ravi", "Anil", "neha"]\nprint({n.title(): len(n) for n in names if n.lower().startswith("a")})', "Make the check case-proof with `lower()`, then build `key: value` with `title()` for the key."),
]
